<style>
:root{--ink:#18313c;--muted:#617b87;--line:#d9e8ea;--teal:#0c7882;--soft:#eef8f8;--gold:#bf8837;--bg:#f2f8f9;--red:#ab4256}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink)}
a{color:var(--teal);text-decoration:none}.wrap{max-width:1500px;margin:auto;padding:25px clamp(14px,3vw,44px) 65px}
.top{background:#102b37;color:white;border-radius:23px;position:relative;overflow:hidden;padding:29px 34px 26px;box-shadow:0 20px 60px #102b3728}.top:before{content:"";position:absolute;width:420px;height:420px;right:-50px;top:-240px;border-radius:50%;border:60px solid #ffffff10;box-shadow:0 0 0 80px #ffffff08}.top-inner{position:relative;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.brand{font-size:12px;text-transform:uppercase;letter-spacing:.17em;color:#7ce0d8;font-weight:800}.top h1{font-size:clamp(25px,3vw,42px);line-height:1.12;letter-spacing:-.035em;margin:12px 0 8px}.top p{color:#c6d9dc;max-width:660px;margin:0}.hero-mark{font-size:55px;line-height:1;filter:drop-shadow(0 10px 20px #0004)}.top .tag{display:inline-block;margin-top:15px;background:#ffffff16;border:1px solid #ffffff24;border-radius:99px;padding:5px 12px;color:#e2f5f4;font-size:12px}.back{color:#d9f0ee;background:#ffffff13;border:1px solid #ffffff36;border-radius:9px;padding:9px 13px;display:inline-block}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:21px 0}.tabs a{border:1px solid var(--line);padding:9px 14px;border-radius:10px;background:white;font-weight:700}.tabs a:hover{background:#e7f7f5}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:17px}.span7{grid-column:span 7}.span5{grid-column:span 5}.span12{grid-column:span 12}
.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:21px;box-shadow:0 8px 26px #17536a09}.card h2{font-size:18px;margin:0 0 6px;letter-spacing:-.015em}.small{font-size:12px;color:var(--muted)}.big{font-size:29px;font-weight:800;letter-spacing:-.03em}.head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:14px;flex-wrap:wrap}
.eyebrow{font-size:11px;color:var(--teal);font-weight:850;text-transform:uppercase;letter-spacing:.1em}.badge{display:inline-flex;align-items:center;border-radius:99px;padding:5px 10px;background:#e5f5f4;color:#176b70;font-size:11px;font-weight:800}.badge.voting{background:#fff2dc;color:#946020}.badge.denied,.badge.false,.badge.withdrawn,.badge.expired{background:#fceced;color:#9c4654}.badge.finished,.badge.inconclusive{background:#edf2f4;color:#5f7480}.badge.notice,.badge.response_received{background:#fff1df;color:#946020}.badge.substantiated{background:#e9f5f1;color:#23755b}
button,.button{border:0;background:var(--teal);color:white;font:inherit;font-weight:750;border-radius:9px;padding:10px 15px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center}.button.ghost,button.ghost{background:white;border:1px solid #b9d6da;color:var(--teal)}button.red{background:#a44859}button:disabled{opacity:.5;cursor:not-allowed}input,select,textarea{width:100%;border:1px solid #c8dfe2;background:#fff;border-radius:9px;padding:10px;font:inherit;color:var(--ink)}textarea{min-height:75px;resize:vertical}label{font-size:12px;color:#49616b;font-weight:750;display:block;margin-bottom:5px}.field{margin:0 0 11px}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.row>*{flex:0 0 auto}.stack{display:grid;gap:12px}.item{border:1px solid #e1edf0;background:#fcfefe;border-radius:12px;padding:14px}.item h3{font-size:14px;margin:0 0 2px}.meta{color:var(--muted);font-size:12px}.item-top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}.progress{height:8px;background:#e8f0f1;border-radius:99px;overflow:hidden;margin:12px 0 6px}.progress span{display:block;height:100%;background:linear-gradient(90deg,#19a4a2,#65cdb0);border-radius:99px}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.divider{height:1px;background:var(--line);margin:13px 0}.counter{font-variant-numeric:tabular-nums;font-weight:800;color:var(--teal)}.notice{background:#e9f7f5;border:1px solid #bfe4df;padding:11px 13px;border-radius:9px;margin:15px 0}.notice.error{background:#fff0f1;border-color:#f2c9d0;color:var(--red)}.empty{color:var(--muted);padding:18px;text-align:center;background:#f7fbfb;border-radius:10px}.fine{background:#fcf6ec;border:1px solid #eeddbd;border-radius:12px;padding:12px;color:#6b593c;font-size:12px}.foot{margin-top:22px;color:var(--muted);font-size:12px}
@media(max-width:950px){.span7,.span5{grid-column:span 12}}@media(max-width:570px){.wrap{padding:12px 10px 42px}.top{padding:22px}.card{padding:15px}.two{grid-template-columns:1fr}}
</style>
