</div><script>(function(){function tick(){document.querySelectorAll('.countdown').forEach(function(el){var s=Math.max(0,Math.ceil((new Date(el.dataset.end).getTime()-Date.now())/1000));el.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')})}tick();setInterval(tick,1000)})();</script></body></html>
